CREATE TYPE public.app_role AS ENUM ('admin','estimation_manager','estimator','viewer');
CREATE TYPE public.resource_type AS ENUM ('material','labor','equipment','subcontractor');
CREATE TYPE public.project_status AS ENUM ('studying','submitted_to_medial_man','submitted_to_client','waiting_for_reply','inquiries_sent','answers_received','on_hold','client_rejected','construction_ongoing','construction_complete','finished','closed');
CREATE TABLE public.user_roles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,role public.app_role NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_roles ON public.user_roles FOR SELECT TO authenticated USING(auth.uid()=user_id);
CREATE FUNCTION public.handle_new_user() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,'estimator'); RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.handle_new_user() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER on_auth_user_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.handle_new_user();
CREATE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid,public.app_role) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) TO authenticated;
CREATE TABLE public.projects(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,name text NOT NULL,client_name text,location text,status public.project_status NOT NULL DEFAULT 'studying',estimated_value numeric DEFAULT 0,budget numeric DEFAULT 0,start_date date,end_date date,submission_date date,technical_requirements text,financial_requirements text,notes text,project_no bigint,code text,area text,scope_of_work text,contract_type text,tender_entry_date date,last_submit_date date,last_rfi_date date,note text,duration text,excel_headers jsonb,excel_pre_headers jsonb,excel_sheets_order text[],created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.projects TO authenticated; GRANT ALL ON public.projects TO service_role;
ALTER TABLE public.projects ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_projects ON public.projects FOR ALL TO authenticated USING(auth.uid()=user_id) WITH CHECK(auth.uid()=user_id);
CREATE TABLE public.resources(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,project_id uuid REFERENCES public.projects(id) ON DELETE CASCADE,type public.resource_type NOT NULL,code text,name_ar text NOT NULL,unit text NOT NULL,unit_price numeric(14,2) NOT NULL DEFAULT 0,notes text,division text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.resources TO authenticated; GRANT ALL ON public.resources TO service_role;
ALTER TABLE public.resources ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_resources ON public.resources FOR ALL TO authenticated USING(auth.uid()=user_id) WITH CHECK(auth.uid()=user_id AND (project_id IS NULL OR EXISTS(SELECT 1 FROM public.projects p WHERE p.id=project_id AND p.user_id=auth.uid())));
CREATE TABLE public.boq_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,project_id uuid REFERENCES public.projects(id) ON DELETE CASCADE,parent_id uuid REFERENCES public.boq_items(id) ON DELETE CASCADE,item_no text NOT NULL,description_ar text NOT NULL,description_en text,unit text,quantity numeric(14,3) DEFAULT 0,material_cost numeric(14,2) DEFAULT 0,labor_cost numeric(14,2) DEFAULT 0,equipment_cost numeric(14,2) DEFAULT 0,subcontractor_cost numeric(14,2) DEFAULT 0,is_group boolean NOT NULL DEFAULT false,level integer NOT NULL DEFAULT 0,sort_order integer NOT NULL DEFAULT 0,sheet_name text,raw_row jsonb,cell_styles jsonb,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,project_id,sheet_name,item_no));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.boq_items TO authenticated; GRANT ALL ON public.boq_items TO service_role;
ALTER TABLE public.boq_items ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_boq ON public.boq_items FOR ALL TO authenticated USING(auth.uid()=user_id) WITH CHECK(auth.uid()=user_id AND (project_id IS NULL OR EXISTS(SELECT 1 FROM public.projects p WHERE p.id=project_id AND p.user_id=auth.uid())));
CREATE TABLE public.price_analysis_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,project_id uuid REFERENCES public.projects(id) ON DELETE CASCADE,boq_item_id uuid NOT NULL REFERENCES public.boq_items(id) ON DELETE CASCADE,resource_id uuid REFERENCES public.resources(id) ON DELETE SET NULL,resource_type public.resource_type NOT NULL,description_ar text NOT NULL,description_en text,unit text NOT NULL,quantity numeric(14,4) NOT NULL DEFAULT 0,unit_price numeric(14,2) NOT NULL DEFAULT 0,cell_styles jsonb,sort_order integer NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.price_analysis_items TO authenticated; GRANT ALL ON public.price_analysis_items TO service_role;
ALTER TABLE public.price_analysis_items ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_pa ON public.price_analysis_items FOR ALL TO authenticated USING(auth.uid()=user_id) WITH CHECK(auth.uid()=user_id AND EXISTS(SELECT 1 FROM public.boq_items b WHERE b.id=boq_item_id AND b.user_id=auth.uid()));
CREATE TABLE public.price_analysis_markup(boq_item_id uuid PRIMARY KEY REFERENCES public.boq_items(id) ON DELETE CASCADE,user_id uuid NOT NULL,project_id uuid REFERENCES public.projects(id) ON DELETE CASCADE,indirect_pct numeric(6,2) NOT NULL DEFAULT 5,overhead_pct numeric(6,2) NOT NULL DEFAULT 8,risk_pct numeric(6,2) NOT NULL DEFAULT 3,profit_pct numeric(6,2) NOT NULL DEFAULT 10,updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.price_analysis_markup TO authenticated; GRANT ALL ON public.price_analysis_markup TO service_role;
ALTER TABLE public.price_analysis_markup ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_markup ON public.price_analysis_markup FOR ALL TO authenticated USING(auth.uid()=user_id) WITH CHECK(auth.uid()=user_id AND EXISTS(SELECT 1 FROM public.boq_items b WHERE b.id=boq_item_id AND b.user_id=auth.uid()));
CREATE TABLE public.project_files(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,project_id uuid NOT NULL REFERENCES public.projects(id) ON DELETE CASCADE,file_name text NOT NULL,file_path text NOT NULL,file_size bigint,file_type text,category text,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.project_files TO authenticated; GRANT ALL ON public.project_files TO service_role;
ALTER TABLE public.project_files ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_files ON public.project_files FOR ALL TO authenticated USING(auth.uid()=user_id) WITH CHECK(auth.uid()=user_id AND EXISTS(SELECT 1 FROM public.projects p WHERE p.id=project_id AND p.user_id=auth.uid()));
CREATE FUNCTION public.update_updated_at_column() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN NEW.updated_at=now(); RETURN NEW; END $$;
CREATE TRIGGER update_projects_updated_at BEFORE UPDATE ON public.projects FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();
CREATE INDEX idx_projects_user_id ON public.projects(user_id); CREATE INDEX idx_boq_user_parent ON public.boq_items(user_id,parent_id,sort_order); CREATE INDEX idx_resources_user_type ON public.resources(user_id,type); CREATE INDEX idx_pa_boq_sort ON public.price_analysis_items(boq_item_id,sort_order); CREATE INDEX idx_project_files_project_id ON public.project_files(project_id);
CREATE POLICY own_storage_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='project-files' AND auth.uid()::text=(storage.foldername(name))[1]);
CREATE POLICY own_storage_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='project-files' AND auth.uid()::text=(storage.foldername(name))[1]);
CREATE POLICY own_storage_update ON storage.objects FOR UPDATE TO authenticated USING(bucket_id='project-files' AND auth.uid()::text=(storage.foldername(name))[1]) WITH CHECK(bucket_id='project-files' AND auth.uid()::text=(storage.foldername(name))[1]);
CREATE POLICY own_storage_delete ON storage.objects FOR DELETE TO authenticated USING(bucket_id='project-files' AND auth.uid()::text=(storage.foldername(name))[1]);